export type ModuleStatus = "live" | "partial" | "roadmap";

export type FeatureModule = {
  key: string;
  name: string;
  status: ModuleStatus;
  description: string;
};

// Honestly flagged against what this build actually does — not what the
// product could eventually cover. An inflated feature map is the fastest
// way to lose credibility with a finance buyer who clicks into things.
//
// `key` is a stable slug used only by module_role_visibility (see that
// migration) to remember which roles a super admin has restricted a
// module to on the Full Feature Map page — it has no meaning anywhere
// else in the app and isn't a database foreign key, since this catalog
// itself is code, not a table.
export const MODULES: FeatureModule[] = [
  { key: "employee_management", name: "Employee Management", status: "live", description: "Employee CRUD, TIN/PFA/bank account (NUBAN) capture, an auto-generated Employee ID (an 8-character badge/staff number, globally unique, distinct from the row's internal id, assigned by the database the moment an employee is added — never typed in by hand) alongside email as a second way to identify someone, self-service account creation from Security & Access rather than an emailed invite (a generated password shown once for admin to hand over directly, or the Employee ID itself for anyone with no email at all), a read-only per-employee view with a merged activity timeline (leave, loans, expenses, overtime, leave encashment, status and compensation changes, payslips — each with its existing status badge) alongside the edit form, department assignment for cost-centre reporting, job grades with salary bands (the edit page flags an employee whose annual pay falls outside their assigned grade), manager assignment with a company-wide Org Chart view (cycle-safe — a manager loop can't be created or rendered), date of birth / nationality / residential contact address capture, probation end date and a confirmed flag (surfaced as an Overdue/Ends soon/On probation badge in the directory — a company-policy date, not a statutory probation length, since Nigerian law doesn't legislate one), employment type (permanent/contract/intern) and contract end date (surfaced as an Expired/Ends soon/Active contract directory badge, computed fresh on every page load — a separate daily pg_cron job independently pushes an in-app, and optionally emailed, notification to admin/hr_manager once either deadline is within 14 days, so the alert fires whether or not anyone opens this page), directory search/filter by name/status/department/branch (server-side, 50 per page once an org grows past that), branch assignment (a work-location record — name, state, address — for cost-centre/location reporting; it does not drive PAYE routing, which stays keyed off each employee's own state of residence), a Suspended status distinct from Active/Terminated (excluded from regular pay runs the same way any non-active status already was, with zero query changes — but unlike Terminated, it doesn't revoke self-service access or trigger Final Settlement eligibility, since both of those stay keyed specifically to the terminated status), an auto-logged status-change history (never client-written) shown per employee, an onboarding checklist for any non-terminated employee (documentation collected, contract signed — probation tracking and confirmation are handled separately by the existing probation fields; \"documentation collected\" can only be ticked once at least one file actually exists in that employee's document repository below, enforced both in the Server Action and by a database trigger, and it un-ticks itself automatically if every document is later deleted), and — for a terminated employee — an offboarding checklist (notice period served, assets returned, clearance obtained, experience letter issued) alongside read-only indicators for the two steps that are already automatic (access revocation, final settlement status). Neither checklist generates or e-signs any document — both only track whether a step happened. A per-employee document repository (Supabase Storage-backed, private bucket, admin/HR-uploaded with an optional free-text type label) lets an employee view and download their own files from /me, alongside admin/HR upload and delete from the edit page — generic storage, not a structured document taxonomy or e-signature. DOB isn't yet wired into any pension-age eligibility rule and nationality isn't yet wired into expatriate PAYE treatment — both are open statutory questions this build doesn't guess at. Neither probation status nor employment type is wired into payroll math — pay is computed identically regardless of either. A profile photo (JPEG/PNG/WebP, 5MB max) shows as a round image at the top of the View Employee page — admin/HR can upload or replace it from the edit page; anyone who could already view that employee's record (org staff, the employee themselves, their manager) can see it, stored in a private Supabase Storage bucket with a signed URL per request, same as the document repository below. No photo on file falls back to the employee's initials." },
  { key: "payroll_setup", name: "Payroll Setup", status: "live", description: "Company setup during onboarding: pay frequency, PFA default, states of operation. Reached only by whoever provisions the very first login for a new org — there's no public signup that creates one on demand (see Security)." },
  { key: "salary_structure", name: "Salary Structure", status: "live", description: "Basic / housing / transport pay components per employee." },
  { key: "earnings_management", name: "Earnings Management", status: "live", description: "Weekly/biweekly/monthly, 13th Month (one month's basic), discretionary Bonus, and Arrears/retroactive pay (all admin-entered per employee) frequencies are all real, each taxed on top of year-to-date. Off-cycle exists via Final Settlement specifically. Arrears is taxed under whichever rules are in force when it's paid, not the rules in force for the period it relates to — a product decision, not yet confirmed against a Nigerian tax professional (see Tax Management) — and, like bonus/13th month, isn't pensionable or NHF-deductible even where the shortfall being repaid originally would have been. A required note on every arrears line records which period it relates to and why, for the audit trail." },
  { key: "deductions", name: "Deductions", status: "live", description: "PAYE, pension, NHF, loan repayments and benefit contributions, all itemised per payslip. Deduction priority is explicit and enforced: statutory deductions are never skipped, loans are capped against whatever net pay remains, and a benefit enrollment whose employee cost can't be fully covered by what's left is skipped in its entirety that run (earliest-enrolled first) rather than partially charged — net pay can never go negative, backstopped by a database check constraint." },
  { key: "attendance_integration", name: "Attendance Integration", status: "live", description: "Weekly Present/Late/Absent grid; unrecorded absences deduct pay automatically." },
  { key: "shift_scheduling", name: "Shift Scheduling", status: "live", description: "A forward-looking shift roster — which shift (e.g. Morning 08:00–16:00) an employee is scheduled to work on a given day — distinct from and unconnected to Attendance Integration's after-the-fact Present/Late/Absent grid; assigning a shift doesn't imply attendance, and marking attendance doesn't require a shift assignment to exist. Admin/HR Manager define the org's shift-type catalog (name, start/end time) from /shifts/templates; Department Manager builds their own department's weekly roster from the same additive, department-scoped RLS this session already gave that role for leave and overtime — a day-to-day operational task, not something reserved for HR the way Employee Relations cases are. Every employee sees their own upcoming shifts (next 14 days) as self-service, the same shared-page-RLS-decides-visibility shape as Performance Management and Recruitment. Assigning or changing a shift notifies the affected employee. Auditor reads every assignment org-wide, read-only, matching every other sensitive-record table. Not built: shift swap requests between employees, recurring/repeating shift patterns (every assignment is a discrete day), or overnight-shift-aware payroll integration (a shift crossing midnight is stored as a single start/end time pair, same as the existing shift_templates.end_time being earlier than start_time for an overnight shift — display-only, not wired into any payroll calculation)." },
  { key: "leave_management", name: "Leave Management", status: "live", description: "Leave requests, balances, admin/HR/manager approval, unpaid leave deducts pay. Leave encashment — cashing out unused annual leave for money while still employed, distinct from Final Settlement's termination-only leave payout — is admin/payroll_manager-approved with an atomic balance check (rejects and rolls back cleanly if the employee doesn't have enough days) and pays out taxable, non-pensionable income through the next pay run." },
  { key: "overtime_management", name: "Overtime Management", status: "live", description: "Employee-submitted overtime requests, admin/payroll approval with a 1.5×/2× rate, paid via next pay run as taxable (non-pensionable) pay." },
  { key: "loans_advances", name: "Loans & Advances", status: "live", description: "Employee-initiated requests, admin/payroll approval, automatic net-pay repayment." },
  { key: "tax_management", name: "Tax Management", status: "live", description: "Cumulative PAYE on the Nigeria Tax Act 2025 (effective 1 January 2026) bands, re-derived every run. Arrears/retroactive pay is taxed the same way, under whichever rules are in force when it's paid rather than the rules in force for the period it relates to — a period-of-receipt product decision, not yet confirmed against a Nigerian tax professional, for pay that crosses a rule-version boundary (see Earnings Management). The public PAYE Calculator also solves net-to-gross (gross-up) for a target take-home; gross-up against a real employee's own pay components isn't wired into pay-run creation yet. Annual tax reconciliation (per-employee yearly gross/PAYE/pension/NHF, CSV export) is live, and a printable annual tax certificate can be generated from that same data per employee — admin/HR from the reconciliation report or the employee's own record, self-service from /me. Direct e-filing to NRS/state IRS is not built." },
  { key: "benefits_administration", name: "Benefits Administration", status: "live", description: "HR-managed plan catalog and enrollment; employer cost and employee deduction per pay run." },
  { key: "payroll_processing", name: "Payroll Processing", status: "partial", description: "Regular (weekly/biweekly/monthly), 13th Month, Bonus and Arrears runs now land as a Draft — every side effect (loan repayments, expense/overtime/leave-encashment payouts, unpaid-leave and absence deductions) posts immediately so the draft's numbers are real, but the run itself isn't final: an admin/payroll_manager must explicitly Approve it before it counts toward reports, reconciliation, tax certificates or GL export, or Discard it instead, which fully reverses every one of those side effects (loans/expenses/leave/attendance/overtime restored, journal entries deleted, the run itself removed) rather than just correcting the ledger the way reversal does. The 25%+ gross-variance flag on a regular-frequency run's detail page now has real teeth — it's the signal to discard before approving, not just to reverse after the fact. Final Settlement is deliberately not part of this gate: it still posts immediately, since its pay run is a required, non-discardable marker of settlement eligibility rather than a run someone might want to undo. Admin-only reversal remains the correction path for an already-approved run — it posts a correcting journal entry and now also restores every side effect the run consumed (loan balances, expense/leave/overtime/leave-encashment approvals back to a re-payable state), the same restoration discard already gives a draft. What it still doesn't do: address already-remitted statutory amounts, or say whether a reversal after a filing deadline requires an amended filing — both remain open questions. New-hire pay is prorated to actual days employed this period, termination mid-period proration is handled by Final Settlement, and a mid-period basic/housing/transport change splits that period's pay across every rate it was actually paid at by calendar days, using an auto-logged compensation-history table (mirrors the employee status-history pattern — never a client-chosen effective date, just the day the change was saved). Every change within the period gets its own segment, not just the first — a second or third change in the same period is prorated correctly rather than folded into the first segment." },
  { key: "payslips", name: "Payslips", status: "live", description: "Itemised digital payslips with a step-by-step \"· how?\" derivation of every figure. Every individual payslip now has its own printable/save-as-PDF page — reached from a payroll run's payslip table (any role that can see the run) or, for an employee's own record, from /me/payslips — a full paginated history of every payslip from a posted (never draft) pay run, its own sidebar link for the Employee role, linked from the \"Latest payslip\" card on /me as well (self-service, ownership-checked, never another employee's) — reusing the exact same derivation breakdown rather than a separate summary." },
  { key: "document_generation", name: "Document Generation", status: "partial", description: "Employment & Salary Certificate, an Offer/Confirmation Letter, and a Contract of Employment — all printable documents generated on demand from live records (never a stored/stale copy). Admin/HR can generate any of the three for any employee (respecting salary masking); every employee can generate their own from /me (their own salary always shows, since masking hides figures from other viewers, not from the employee themselves). The contract uses standard, generic terms drawn from what's on file — role, compensation, probation, leave entitlement, a plain-English termination clause pointing at the Nigerian Labour Act rather than inventing a specific notice period — disclosed as not lawyer-reviewed language for a binding agreement. Tax documents (annual reconciliation, tax certificate) live under Tax Management. E-signature is not built — that needs either a third-party provider or a custom consent/audit-trail system, a materially different scope from template generation." },
  { key: "direct_deposit_payments", name: "Direct Deposit & Payments", status: "roadmap", description: "Employee bank account capture is real and checksum-validated against the CBN's NUBAN check-digit algorithm for a curated list of ~25 major Nigerian banks (an \"Other\" option covers any unlisted institution, enforcing the 10-digit format only). This confirms the account number is internally consistent with the selected bank's own numbering — it does not confirm the account exists or belongs to the named holder, which needs a live bank-verification API this build doesn't call. Integrations shows real coverage. Net pay is posted to the ledger; still no bank disbursement file or transfer integration." },
  { key: "expense_reimbursement", name: "Expense Reimbursement", status: "live", description: "Claims, admin/payroll approval with taxable/non-taxable treatment, paid via next run." },
  { key: "compliance", name: "Compliance", status: "live", description: "PAYE, pension, NHF, NHIS, NSITF, ITF and WHT schemes with TIN gating before every run." },
  { key: "employee_self_service", name: "Employee Self-Service", status: "live", description: "Payslips, leave, loans, expenses, benefits and notifications in one dashboard." },
  { key: "manager_self_service", name: "Manager Self-Service", status: "live", description: "Direct-report roster and leave and overtime approval for any employee with reports, from the same /team page. Overtime joined leave as a second direct-manager approval this build: unlike leave, approving overtime never touches a table (like an employee's leave balance) a manager lacks a general update right on, so it needed only two additive RLS policies mirroring the existing admin/payroll_manager ones — the existing approveOvertime/rejectOvertime actions already relied entirely on RLS, so no app code changed for the write path itself to start working. Loans and expenses stay admin/payroll_manager-only, unchanged — a payroll/finance decision, not a day-to-day scheduling one a direct manager is naturally placed to judge. Department Manager is a separate, now-enforced org_membership role rather than this manager_id linkage — its scope is the whole department the manager's own employee record belongs to (via additive RLS keyed on department_id, not direct reports), so it works even with zero direct reports, and /team shows the department's full roster and pending leave for that role specifically; department_manager's own approval scope stays leave-only for now, matching what's actually seeded in role_permissions." },
  { key: "role_dashboards", name: "Per-Role Dashboards", status: "live", description: "/dashboard replaces the same three static org-info fields every non-employee role used to see with real widgets scoped to that role's own domain: pending approvals (admin/payroll_manager/hr_manager/department_manager), the most recent pay run (admin/payroll_manager/finance_manager), workforce headcount and upcoming contract/probation deadlines (admin/hr_manager/department_manager), recent authentication audit activity (admin/auditor/finance_manager), AP/AR outstanding totals (admin/payroll_manager/accountant/finance_manager), active budgets (admin/finance_manager), job grades and benefit enrollment (admin/compensation_benefits_manager/hr_manager), the recruitment pipeline (admin/hr_manager), the active performance review cycle (admin/hr_manager), and — for Department Manager specifically — its own department's roster and pending leave. Which roles see which widget is admin-configurable per org from Security &amp; Access → Dashboard visibility, the same additive \"zero rows = default, any rows = authoritative override\" convention Module Visibility already established for the Full Feature Map — except a dashboard widget's own default is a sensible narrow role set coded per widget, not \"everyone,\" since not every widget makes sense for every role the way a documentation page entry does. Presentation-only: every widget's data still goes through the exact same RLS every other page in this app already relies on, so a widget shown to an unintended role would at worst render an empty or zero state, never leak anything. Admin additionally gets a \"View as\" role-preview switcher directly on /dashboard — a plain ?viewAs= query param, not a session or permission change — showing exactly which widgets another role's catalog would render, with an explicit banner making clear every widget still queries under the admin's own real data access, not that role's, and a one-click exit back to their own view. Employee keeps its existing self-service /me dashboard unchanged — this replaces every other role's Overview page only." },
  { key: "reporting_analytics", name: "Reporting & Analytics", status: "live", description: "Statutory liability totals, PAYE-by-state breakdowns, and a per-run payroll register with a ledger-balanced reconciliation check for every pay run, including reversals. Draft runs are listed for the audit trail but excluded from totals and from every other statutory/reconciliation view until approved. The payroll register now pages through pay runs 25 at a time rather than loading every run in an org's history at once, while its totals footer stays computed across the org's entire posted history via a dedicated database aggregate — pagination speed and totals correctness never trade off against each other. Every real table or report across the app — the employee directory, every workflow queue (leave, loans, expenses, overtime, benefits), every accounting module (chart of accounts, vendors/bills, customers/invoices, general ledger, financial statements, bank reconciliation, fixed assets, budgets), the payroll register, compliance schemes, the security member list and audit log, a manager's team roster — now has a one-click CSV export button, generated client-side from exactly the rows already on screen so it can never show a different number than the table above it (never a separate server round-trip re-querying the data). The heavier report-style pages (Profit &amp; Loss, Balance Sheet, a single budget's comparison, a single bank reconciliation, the statutory compliance reference, the org chart) also get a Print/Save as PDF button, and a real bug in how printing worked at all — the sidebar and mobile nav bar had no print-hide rule, so anything printed risked including them and being clipped to one screen's height — is fixed at the app-shell level, benefiting every printable page including the pre-existing employment/tax certificates. Final Settlement gained a printable pre-processing preview and a permanent post-processing receipt page per settlement." },
  { key: "accounting_integration", name: "Accounting Integration", status: "partial", description: "Real, fully itemised general-ledger CSV export per pay run, with each employee's department attributed as a cost centre. A browsable General Ledger &amp; Trial Balance report now sits alongside that export — every posting across every source (payroll, final settlement, accounts payable, accounts receivable), filterable by date, grouped into a proper trial balance by account type with a visible debits-equal-credits total, plus the full chronological journal-entry detail underneath, now paged 25 at a time on screen while the trial balance and both CSV exports still total every matching entry, not just the visible page. No live accounting-software API sync (QuickBooks, Xero, Sage) yet." },
  { key: "chart_of_accounts", name: "Chart of Accounts", status: "live", description: "A real, per-org, admin/payroll_manager-manageable table (asset/liability/equity/revenue/expense, code, name, description) replacing what used to be a flat hardcoded map — every account payroll, final settlement, accounts payable and accounts receivable already post to is seeded automatically for every org (existing orgs via migration, new orgs at creation), and admin can add custom accounts for anything specific to their business. System accounts can't be deleted, only added-to. Deliberately not a hard foreign-key constraint from ledger_postings.account_code — every existing posting path computes its code in application code, and a live system already processing real pay runs isn't the place to make an org/code mismatch a hard failure; the chart is the authoritative editable reference other reports label against, not (yet) a database-enforced one." },
  { key: "accounts_payable", name: "Accounts Payable", status: "partial", description: "Real double-entry against the same general ledger payroll already posts to — the first ledger domain in this build that isn't payroll-driven. Vendor records with bank details, and a bill lifecycle (raised → approved → paid) that admin/payroll_manager works through from Vendors and Bills: approving a bill debits an expense account and credits Accounts Payable — recognizing the liability immediately, on an accrual basis, not when cash actually moves. Approved bills are now paid individually or as a batch — select several and pay them together in one action, posting a single aggregate journal entry (debit Accounts Payable, credit Cash & Bank for the combined total) that every bill in the batch shares, mirroring how a pay run posts once per run rather than once per employee. Recurring bills are a per-vendor template (amount, description, cadence — weekly/monthly/quarterly/annually) that a daily background job turns into a new pending-approval bill on schedule; approving and paying each instance is still a deliberate step every time, never automated. Every vendor now has a printable/exportable statement — every bill and payment posted for them, with a running balance, optionally filtered to a date range. Every posting goes through the same balance-enforced ledger payroll uses — an unbalanced entry is a database-level impossibility, not just a UI convention. Accountant gets read access to vendors, bills and the ledger itself, the first real payoff for that role. Pending and approved bills always show every one of them — it's a work queue, not a history — while the settled list (rejected/paid) pages 25 at a time once it grows past that. Not built: supplier-side payment batches that mix vendors across currencies, multi-currency (every money value in this build is an integer Naira-kobo column — a real architecture change, not an incremental addition)." },
  { key: "accounts_receivable", name: "Accounts Receivable", status: "partial", description: "The revenue-side mirror of Accounts Payable, against the same general ledger. Customer records, and an invoice lifecycle (draft → issued → paid, or draft → void) that admin/payroll_manager works through from Customers and Invoices: issuing an invoice debits Accounts Receivable and credits Sales Revenue — recognizing revenue immediately, on an accrual basis, not when cash is actually collected. An issued invoice now takes partial payments — each one debits Cash & Bank and credits Accounts Receivable for whatever amount was actually received, capped at what's still outstanding, and the invoice only flips to Paid once every payment (and credit note) together fully covers it; the full payment history is kept, not just a single settlement date. A credit note reduces what's owed without any cash movement — it debits whichever revenue account the original invoice actually credited and credits Accounts Receivable, reversing that much recognized revenue, capped the same way at what's outstanding. Recurring invoices are a per-customer template (amount, description, cadence) that a daily background job turns into a new draft invoice on schedule — issuing it, which recognizes real revenue, stays a deliberate step every time, never automated. A new aging report breaks every outstanding issued invoice down by customer and by days past due (current / 1-30 / 31-60 / 61-90 / 90+), with CSV export. Every posting goes through the same balance-enforced ledger payroll and accounts payable use. Accountant gets the same read access here it already has for accounts payable. Drafts and issued invoices always show every one of them — it's a work queue, not a history — while the settled list (paid/void) pages 25 at a time once it grows past that. Not built: multi-currency (every money value in this build is an integer Naira-kobo column — the same architecture change flagged out of scope for Accounts Payable, not an incremental addition)." },
  { key: "financial_statements", name: "Financial Statements", status: "live", description: "Profit &amp; Loss and Balance Sheet, both derived live from the general ledger — no separately entered figures to drift out of sync with the postings underneath. Profit &amp; Loss sums every revenue and expense account over a date range — defaulting to the current year to date rather than scanning the entire ledger on every visit, with an explicit \"view all time\" link one click away — to a net income/loss figure. Balance Sheet is a point-in-time snapshot as of a single date — every asset, liability and (chart-defined) equity account's cumulative balance — plus a computed \"retained earnings\" line for net income accumulated to date, since this build has no period-close step that would otherwise sweep revenue and expense into a real equity account. That computed line isn't a guess: the fundamental accounting identity (assets = liabilities + equity) falls directly out of every journal entry already being balanced, so the sheet balances exactly by construction, and the page shows that check explicitly rather than asserting it. No cash flow statement, no comparative/prior-period columns, no consolidated multi-entity statements yet." },
  { key: "bank_cash_reconciliation", name: "Bank &amp; Cash Reconciliation", status: "partial", description: "Closes the loop on every module that posts to cash_and_bank (payroll, accounts payable, accounts receivable) by checking the books against the actual bank statement, one period at a time. No live bank feed in this build (see Integrations) — admin/payroll_manager enters the statement's ending balance and its individual lines by hand, then matches each line 1:1 against a real cash_and_bank ledger posting, or — for a bank-only item the books don't have yet, like a fee or interest — posts it directly as a new balanced journal entry (debit/credit the chosen expense or revenue account against cash_and_bank) and matches it in the same step, rather than requiring it to be booked by hand somewhere else first. Whatever's left genuinely unmatched on either side is exactly the classic reconciling items a paper bank reconciliation lists: deposits in transit, outstanding withdrawals, bank fees not yet booked — shown as two separate lists rather than netted away. The summary presents both the textbook adjusted-book and adjusted-bank balances and states plainly whether they tie out. Completing a reconciliation is a control record, not a journal entry — it doesn't post anything — and while completed it's locked against further matching; it can now be reopened, which only flips it back to in progress and clears the completion record, never touching the ledger. Accountant gets the same read-only access here as everywhere else in accounting. Not built: multiple bank accounts (there's still only the single cash_and_bank account the rest of the ledger already posts to — real multi-account support would need threading a bank-account dimension through payroll, AP, AR and fixed assets, the same scale of change as multi-currency, not an incremental addition)." },
  { key: "fixed_assets", name: "Fixed Assets", status: "partial", description: "An asset register with straight-line depreciation posting real double-entry against the same general ledger. Depreciation is a manually triggered, period-based run — like a pay run — that aggregates every active, not-yet-fully-depreciated asset's (cost − salvage) ÷ useful-life-months into one balanced journal entry (debit depreciation expense, credit accumulated depreciation) rather than one posting per asset; a database-level unique constraint blocks accidentally running the same period twice. Disposing an asset removes its cost and accumulated depreciation from the books, records any cash received, and plugs the difference to a single gain/(loss)-on-disposal account — debited for a loss, credited for a gain, one formula handling both directions. accumulated_depreciation is chart-typed \"asset\" but credit-normal by construction (a contra-asset), which the Balance Sheet already handles correctly without any special-casing, since it sums every asset account by debit-minus-credit. Not built: accelerated/declining-balance depreciation, mid-month proration (a run always depreciates a full period regardless of where in it an asset was acquired), asset transfers between cost centres, revaluation, impairment, and modelling how an asset was actually financed (cash vs. accounts payable) at acquisition." },
  { key: "budgets", name: "Budgets", status: "partial", description: "Planned vs. actual, by revenue and expense account, for a date range — the first accounting module in this build that doesn't post anything to the general ledger itself. A budget is a named plan with one target amount per account for the whole period (no monthly/quarterly breakdown yet); actuals are computed live from ledger_postings using the exact same signed-sum logic as Profit &amp; Loss, so a budget report can never drift out of sync with what actually posted. Each line shows budgeted vs. actual, the variance, and whether that variance is favorable or unfavorable — a revenue account exceeding its target is favorable, an expense account exceeding its target isn't, and the page knows the difference rather than just showing a signed number. Anything posted in the period to a revenue/expense account with no budget line at all is called out separately rather than silently excluded. Scoped to revenue and expense accounts only (an operating budget) — capital budgets, cash budgets and balance-sheet targets aren't covered." },
  { key: "workflow_approvals", name: "Workflow & Approvals", status: "live", description: "Leave, loan, expense and benefit-enrollment approval flows across admin/HR/payroll/manager roles. Every delete, approve/reject, discard, reverse, dispose and disconnect action across the whole app — not just here — now shows a confirmation dialog explaining the consequence before it fires, and every button that triggers a server round-trip shows a visible loading state the moment it's clicked, so a slow request never looks like the click did nothing." },
  { key: "notifications", name: "Notifications", status: "partial", description: "Requests and decisions notify the right people; unread counts surface in the sidebar and on /me. A contract nearing its end date or an employee approaching the end of probation now also notifies admin/hr_manager directly (once per approaching deadline, re-arming if the date is later changed) — checked both on employees-list page load and once daily by a real pg_cron background job, so it fires independently of anyone visiting that page. A second daily pg_cron job reminds the right approver — admin/payroll_manager for loans, expenses, overtime and leave encashment; admin/hr_manager for leave — once a pending request has sat 3+ days untouched, one reminder ever per request. Every notification, of any kind, now also attempts an email via Resend, sent directly from Postgres (pg_net) with the API key and from-address read from Supabase Vault — until an operator configures those secrets it silently stays in-app only, which is this build's actual state today (no live Resend account connected). Statutory-deadline reminders remain unbuilt." },
  { key: "company_policies", name: "Company Policies", status: "live", description: "Admin/HR-authored policy documents with a per-employee acknowledgement tracker. Editing a policy marks every prior acknowledgement stale (a timestamp comparison, not a versioned document history) and every linked employee account is notified to re-acknowledge. Status (Acknowledged / Needs re-acknowledgment / Not acknowledged) is computed on page load — unlike contract/probation deadlines, this isn't yet one of the checks the daily pg_cron job runs, so there's no scheduled reminder push for it yet." },
  { key: "recruitment_ats", name: "Recruitment / ATS", status: "live", description: "A genuinely new module — unlike Auditor, Department Manager and Performance Management, there was no existing schema to build on. A job requisition (title, department, job grade, description, open/on_hold/closed/filled status) is what candidates apply against — one candidate row per requisition, not a many-to-many candidates-and-applications model, kept deliberately simple. A candidate moves through applied → screening → interviewing → offer → hired/rejected, admin/hr_manager-managed throughout. Scheduling an interview picks any active, linked employee as the interviewer — an interviewer isn't necessarily hr_manager or admin, it can be anyone asked to sit in — and notifies them; that person then sees a \"Your interviews\" section on the shared /recruitment page (visible to everyone, the same RLS-decides-what-you-see shape as Performance Management) where they record their own outcome and notes, without needing any HR access to anything else. Hiring a candidate creates a real, bare employee record directly (name, email, department, job grade, hire date) and links back via the candidate's hired_employee_id — the one integration point connecting this module to the rest of the app — but deliberately leaves compensation, banking, TIN and a login for the existing Edit Employee page and Security & Access to fill in afterward, the same two places that already own those steps for any other new hire, rather than duplicating that logic here. No resume file upload — just an optional external link — and no candidate-facing portal; this is an internal pipeline tool only. Auditor reads every requisition, candidate and interview org-wide, matching how it already reads every other HR/payroll record." },
  { key: "employee_relations", name: "Employee Relations", status: "live", description: "Case management for grievances, disciplinary matters and workplace investigations — the Full Feature Map gap-analysis's next priority item after Compensation &amp; Benefits Manager/Finance Manager and Per-Role Dashboards. A case (grievance/disciplinary/investigation, low/medium/high severity) is always about a specific employee; an append-only timeline of notes (note, warning issued, meeting held, escalated, resolved) records what happened on it. Admin/HR Manager have full case management (create, update, resolve, delete); Department Manager can see and open a case for their own department's employees but can't resolve one — that stays an HR/admin function, matching how this role has never been given final sign-off on anything except leave; Auditor reads every case org-wide, read-only, matching every other sensitive-record table. Deliberately, the employee who's the subject of a case gets no in-app visibility at all, at any status — unlike Performance Management's appraisals (an intentionally two-way employee/manager artifact), this is HR case-management tooling, and outcomes are communicated to the employee outside the system, not through self-service. Case notes have no update or delete policy for anyone, admin included, once logged — a kept record, the same immutability convention journal_entries and performance_appraisals already established. Resolving a case is a dedicated function (mirrors review_leave_request/acknowledge_performance_appraisal's security-definer-with-explicit-auth-check shape) that sets status and appends the closing note atomically." },
  { key: "performance_management", name: "Performance Management", status: "live", description: "Goals, appraisals and review cycles — the natural next layer on top of job grades and compensation history, which already model an employee's trajectory. An admin/hr_manager-managed catalog of review cycles (e.g. \"2026 H1 Review\", a period and a draft/active/closed status) is what every goal and appraisal is set against. An employee sets their own goals (title, description, target date) against a cycle and moves them through not started/in progress/completed/cancelled themselves; a direct manager or admin/hr_manager can set one for a report too. An appraisal is authored only by a direct manager or admin/hr_manager, never by the employee being reviewed — one per employee per cycle, with a 1-5 rating, strengths, areas for improvement and manager comments, moving draft → submitted (notifies the employee) → acknowledged. Acknowledging is the employee's only write path onto their own appraisal — a dedicated function, not a general update grant, so they can add their own comment and confirm they've seen it without ever touching the rating or the manager's own comments. Everything lives on one shared /performance page rather than split across role-specific views: RLS alone decides what each visitor sees — their own goals and appraisals always, plus (for a direct manager) their reports' or (for admin/hr_manager) the whole org's, with a \"start appraisal\" prompt for anyone in that scope still missing one this cycle. Department Manager is deliberately not included — unlike leave, no role_permissions row was ever seeded for performance data, so this stays scoped to what's actually been asked for rather than assumed; a department_manager who's also a literal direct manager still gets access the same way any other role would. Auditor reads every goal and appraisal org-wide, matching how it already reads every other HR/payroll record." },
  { key: "security", name: "Security", status: "live", description: "Role-based access across eleven roles (Super Admin, Payroll Manager, HR Manager, Accountant, Department Manager, Employee, Auditor, Compensation &amp; Benefits Manager, Finance Manager / CFO, CHRO, Legal &amp; Compliance), mandatory TOTP MFA for Super Admin and Payroll Manager, an org-scoped authentication audit log (cursor-paged 100 events at a time, since the underlying Supabase Auth log is a single unbounded record shared across every org on the project and can't cheaply support page-number pagination), per-employee salary masking from HR Manager view (a real database-level mask, not just a hidden UI field), and offboarding access revocation — a terminated employee's linked login is redirected away from every self-service route the moment their record is marked exited, re-checked live rather than cached, so a reinstated employee isn't stuck behind a stale gate. This covers the specific \"retained login\" security gap only. Provisioning is fully closed: there is no public sign-up page and no \"Continue with Google\" — both existed at points during this build and were deliberately removed, so every login without exception now originates from an existing admin. Sign-in itself accepts a work email or an Employee ID against the same password (see Employee Management); an Employee-ID-only account is still backed by a real Supabase Auth user under a synthetic, non-deliverable address that's never shown anywhere and never emailed. Admin can also add a Payroll Manager, HR Manager or second Admin directly from Security & Access — the account is created immediately with a generated password shown once on-screen for the admin to hand-deliver, rather than an emailed invite link, since these roles aren't tied to an employee payroll record the way self-service accounts are, or generate logins for every unlinked employee at once. Eleven roles now share a real roles/permissions schema (Super Admin, Payroll Manager, HR Manager, Accountant, Department Manager, Employee, Auditor, Compensation &amp; Benefits Manager, Finance Manager / CFO, CHRO, Legal &amp; Compliance), each with its own default sidebar menu instead of every role seeing the same one — Admin can also override which menu sections show for one specific person from that person's Security & Access page, layered on top of their role's default rather than replacing it, and now which roles can see any given entry on this very Full Feature Map page. Nav-level only: this decides what's visible in the sidebar (or on this page), not what a page or action actually allows, which still comes from the existing per-page role checks. Auditor is now a real, enforced, read-only role rather than a picker option with no backing access: a dedicated set of additive RLS policies (layered on top of every existing policy, never replacing one) grants org-scoped read access across employees (including unmasked salary — an auditor needs the real figures to audit them), payroll runs and payslips, the general ledger and every accounting module (accounts payable, accounts receivable, chart of accounts, bank reconciliation, fixed assets, budgets), leave/loan/expense/overtime requests, final settlements and the org's own authentication audit log, which auditor can now reach directly from the sidebar. Deliberately excluded from that grant: raw employee documents, per-user nav overrides, integration connections and Security & Access member management itself — an auditor can see what happened, not the underlying files or who has access to change it. No write path — action files, page mutations, RLS write policies — grants auditor anything; every table above stays select-only for that role. Department Manager is likewise now real rather than a picker option: an additive, department-scoped (not org-wide) RLS grant, keyed off the department the manager's own linked employee record belongs to rather than direct-report manager_id links, gives it read access to its own department's roster and leave requests plus the ability to approve or reject that department's leave — from the same Manager Self-Service /team page a direct-report manager already uses — while staying invisible to every other department (see Manager Self-Service). Compensation & Benefits Manager and Finance Manager / CFO are the newest two — not new capability, RBAC plumbing on data that already existed under admin/payroll_manager/hr_manager. Compensation & Benefits Manager owns individual employee comp: job grades (full manage, on top of the org-wide read every role already had), unmasked salary and bank fields (joining the same unmask list as admin/payroll_manager/auditor on employees_masked), compensation history, and benefit plans/enrollment. Finance Manager / CFO owns the aggregate financial picture instead — chart of accounts, the general ledger, bank reconciliation, fixed assets, payroll's financial totals (pay runs and payslips, read-only, no unmasked individual salary), and the org's audit log (\"audit preparation\" is an explicit duty) — plus real write and approval power on Budgets specifically, insert/update/delete, not just read, the one place this role gets to act rather than just observe. Neither role touches AP/AR day-to-day operations (vendors, bills, customers, invoices) — that stays Payroll Manager/Accountant's. Wiring these up surfaced a real, independent bug: payroll_manager has had \"payroll.structure.edit\" in role_permissions and the Edit Employee form has gated salary fields on admin/payroll_manager since the feature was built, but no RLS UPDATE policy on employees ever actually included payroll_manager — only admin/hr_manager. A payroll_manager saving an employee edit had every field silently dropped by RLS, reporting success while writing nothing. Fixed alongside these two roles, in the same migration, since it's the same table and the same class of gap. CHRO and Legal &amp; Compliance are the last two from the gap analysis, split the same way Compensation &amp; Benefits Manager and Finance Manager were — one line item, two distinct personas, so two roles rather than one conflated permission set. CHRO is executive-level, read-only visibility across every HR domain — workforce (joining the unmask list on employees_masked, the same \"owns the real figures\" reasoning as Auditor and Compensation &amp; Benefits Manager), recruitment, performance, employee relations, benefits and compensation history, workforce-operational data (leave, overtime, attendance, status history), and workforce cost (pay runs, payslips, final settlements) — but deliberately not accounting/financial tables or the authentication audit log, the same clean split Finance Manager already draws around its own territory. Legal &amp; Compliance is narrower and read-only, focused specifically on legal-exposure and statutory-compliance data: employee relations cases (grievances/disciplinary — direct legal exposure), status history and final settlements (termination compliance), leave/overtime (statutory entitlement compliance), policy acknowledgements, onboarding/offboarding checklists, and — unlike CHRO — the authentication audit log, since that's a security/access-oversight concern, not an HR-operations one. Deliberately not given unmasked salary, recruitment, performance, benefits or compensation history — that's CHRO's territory; employee base records stay masked for this role, the same default every role that isn't explicitly granted the unmask list gets. Neither role has any write path anywhere — pure reporting, same as Auditor." },
  { key: "multi_company_global_payroll", name: "Multi-Company & Global Payroll", status: "roadmap", description: "Nigeria only. Ghana (SSNIT) and Kenya (NSSF/SHIF) rule sets are roadmap, not built." },
  { key: "integrations", name: "Integrations", status: "partial", description: "Bank disbursement connections are a real per-org toggle, but explicitly a demo — no bank API calls, no disbursement file generation." },
  { key: "final_settlement", name: "Final Settlement", status: "live", description: "Exit payroll: prorated regular pay for the partial final period (pensionable and NHF-able, unlike leave payout and gratuity, which are non-pensionable lump sums — all three are taxed together in one cumulative-PAYE calculation), leave payout, gratuity and full loan clearance in one off-cycle run. The final period's last working day comes from the auto-logged status-change history. Rent relief is not re-prorated for that stub period — a disclosed simplification." },
  { key: "learning_management", name: "Learning Management", status: "live", description: "The last item on the Full Feature Map gap-analysis backlog — a lightweight training tracker, not a full e-learning platform: a course is a catalog entry (title, description, category — compliance/onboarding/skills/safety/other — an optional mandatory flag) that can carry an external link and/or directly attached files (slide decks, PDFs, short clips — 20MB per file, Supabase Storage-backed with a signed URL per request, the same private-bucket shape as the employee document repository and profile photos), and an enrollment is admin/hr_manager assigning that course to a specific employee, with a due date. Attached files are visible to every org member (matching the course catalog's own org-wide read access) so an assigned employee can actually reach the content, but only admin/hr_manager can upload or delete one — this still isn't video hosting or a streaming platform, so a multi-gigabyte training video isn't practical, only smaller slide decks, documents and clips. Admin/hr_manager can optionally attach a multiple-choice quiz to a course (up to 4 options per question, exactly one correct, a configurable passing score) — once a course has at least one question, self-report is disabled for it and the employee must pass the quiz to complete it, with unlimited retakes and no per-question feedback after grading (so repeated attempts can't be used to reconstruct the answer key one question at a time). Grading happens entirely server-side: the correct answer for any question is never sent to the client at any point, for any role except admin/hr_manager authoring the quiz — a plain employee gets zero rows querying the quiz tables directly, no matter which columns are asked for, and the only way to see question/option text is a security-definer function that never returns is_correct. Every attempt, passing or not, is a kept record (auditor/hr/chro/legal_compliance-visible, same read scope as the enrollment itself) — the only way one can ever be written is that same grading function, so a graded result can never be hand-entered by any role, admin included. A course with no quiz still completes by employee self-report through a dedicated function, mirroring how acknowledging a performance appraisal is an employee's own write path, never a general update grant. Everything lives on one shared /learning page: an employee's own assigned/completed training (with links to any attached materials, and a \"Take quiz\" link in place of \"Mark complete\" wherever a quiz exists) always shows, plus (for admin/hr_manager) the whole org's completion picture with an assign form, or (for Department Manager) their own department's completion — read-only, since assigning compliance training stays an HR function the same way this session has never let that role finalize anything except leave. Auditor, CHRO and Legal &amp; Compliance all read every enrollment org-wide, read-only, matching every other sensitive-record table this build has added. Admin/hr_manager now manage the whole module — course catalog, attached materials and quizzes — inline from a single /learning landing page rather than a separate /learning/courses screen; that URL now just redirects there, so any existing link or bookmark still lands somewhere useful. Not built: certificates and self-enrollment from a course marketplace — every enrollment is HR-assigned, not employee-initiated." },
  { key: "advanced_features", name: "Advanced Features", status: "partial", description: "Payroll Simulation (what-if analysis across the workforce) is live, and no longer purely observational: an admin can Apply the modeled raise directly, scaling every active employee's basic/housing/transport by the same multiplier the slider showed, in one transaction. It reuses the existing compensation-history trigger unchanged, so every employee's old/new figures land in the same admin/payroll_manager-only audit trail a single manual edit would produce, and the next pay run's mid-period proration correctly treats the change date as a split boundary if a run happens to span it. This is a real, immediate compensation change, not a pay run — nothing is paid out until an actual run is created afterward. Nothing further built here yet." },
];

// A module a super admin has never touched (no rows at all in
// module_role_visibility for its key) stays visible to every role —
// shipping this feature can never silently hide something that was
// visible before. Only once at least one role is explicitly assigned does
// it become visible to just that set.
export function isModuleVisibleForRole(
  moduleKey: string,
  role: string,
  assignmentsByModule: Map<string, Set<string>>,
): boolean {
  const assignedRoles = assignmentsByModule.get(moduleKey);
  if (!assignedRoles || assignedRoles.size === 0) return true;
  return assignedRoles.has(role);
}
